FROM rides
WHERE surge_multiplier > 1.5;

SELECT COUNT(*) AS ride_count
FROM rides
WHERE status = 'cancelled' AND cancellation_reason = 'rider_no_show';

SELECT MAX(temp_max_c) AS highest_temperature_c
FROM external.weather_daily
WHERE city = 'Ottawa' AND date = '2025-07-01';

SELECT AVG(EXTRACT(EPOCH FROM (pickup_time - requested_at)) / 60) AS avg_wait_time_minutes
FROM rides
WHERE status = 'completed';

SELECT COUNT(*) AS ratings_with_comment
FROM ratings
WHERE comment IS NOT NULL;

